_SORTED_KEYS = sorted(RADIO_ABBREVIATIONS.keys(), key=len, reverse=True)
_PATTERN = re.compile(r'\b(' + '|'.join(re.escape(k) for k in _SORTED_KEYS) + r')\b', re.IGNORECASE)

def replace_radio_abbreviations(text: str, lang: str = 'ru') -> str:
    if not text:
        return ''
    norm_lang = (lang or 'en').strip().lower()[:2]
    if norm_lang not in ('en', 'ru', 'de', 'fr', 'es', 'it', 'uk', 'nl'):
        norm_lang = 'en'
    def _repl(m):
        key = m.group(1).upper()
        entry = RADIO_ABBREVIATIONS.get(key)
        if entry:
            return entry.get(norm_lang) or entry.get('en') or m.group(0)
        return m.group(0)
    return _PATTERN.sub(_repl, text)
